(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const x1 = x+w1x, y1 = y+w1y;
  const w2x = Math.sin(x1*0.04+t*0.5)*5 + Math.cos(y1*0.035-t*0.4)*4;
  const w2y = Math.cos(y1*0.04-t*0.45)*5 + Math.sin(x1*0.038+t*0.55)*4;
  const sx = x1+w2x, sy = y1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.65],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*70,0.075,1.8,0.7],
    [200+Math.sin(t*0.7)*90,220+Math.cos(t*0.5+2)*60,0.095,2.4,0.6],
    [300+Math.cos(t*0.4+3)*80,100+Math.sin(t*0.6+1)*55,0.085,2.0,0.8]
  ];
  let aS=0,iS=0,df=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp),inh=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=inh*w; df+=Math.sin(d*f*0.5-t*sp*0.3+a*0.5)*w*0.3;
  }
  const wS=src.reduce((s,p)=>s+p[4],0);
  const act=aS/wS,inh=iS/wS,dn=df/wS;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.5+Math.sin(sx*0.12-sy*0.09+t*2.0)*0.25)/2.75;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
