  let mn=999,mn2=999;
  for(let i=0;i<12;i++){
    const vx=80+(i%4)*120+Math.sin(t*0.3+i*1.7)*25;
    const vy=40+((i/4)|0)*80+Math.cos(t*0.25+i*2.1)*20;
    const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
    if(d<mn){mn2=mn;mn=d;}else if(d<mn2){mn2=d;}
  }
  const ce=Math.min(1,(mn2-mn)*0.15);
  const cell=Math.sin(mn*0.15+t*0.5)*0.3*ce;
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=dn+act*0.4-inh*0.3+spiral*0.5;
  const reaction=Math.tanh((rd1+rd2*0.4)*2.0);
  const micro=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const blend=reaction*0.65+cell*0.15+micro*0.1+dn*0.1;
  const v=blend*0.5+0.5;
  const pal=[[6,12,42],[12,45,78],[18,90,105],[30,140,130],[85,175,145],[180,195,90],[225,170,60],[215,110,55],[185,60,65],[120,30,65],[55,18,65],[20,12,48],[6,12,42]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const cg=ce<0.3?1.1:1.0;
  const tm=lum*edge*cg;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*tm)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*tm)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*tm)|0
  ];
}
